import { useControlledState } from '@rc-component/util';
import { useCallback } from 'react';
import { useRefFunction } from "../../utils";
/**
 * 组合用户的配置和默认值
 *
 * @param param0
 */
const mergeOptionAndPageInfo = ({
  pageInfo
}) => {
  if (pageInfo) {
    const {
      current,
      defaultCurrent,
      pageSize,
      defaultPageSize
    } = pageInfo;
    return {
      current: current || defaultCurrent || 1,
      total: 0,
      pageSize: pageSize || defaultPageSize || 20
    };
  }
  return {
    current: 1,
    total: 0,
    pageSize: 20
  };
};

/**
 * 专门用于处理分页信息更新的 Hook
 * 解决了 total 缺失导致的死循环问题
 */
export function usePageInfo(options) {
  const [pageInfo, setPageInfoStateInner] = useControlledState(() => mergeOptionAndPageInfo(options), undefined);
  const setPageInfoState = useCallback(updater => {
    setPageInfoStateInner(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      options?.onPageInfoChange?.(next);
      return next;
    });
  }, [options?.onPageInfoChange]);
  const setPageInfo = useRefFunction(changePageInfo => {
    const newPageInfo = {
      ...pageInfo,
      ...changePageInfo
    };
    if (newPageInfo.current !== pageInfo.current || newPageInfo.pageSize !== pageInfo.pageSize || newPageInfo.total !== pageInfo.total) {
      setPageInfoState(newPageInfo);
    }
  });
  return [pageInfo, setPageInfo];
}